const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const assets = {};
for (const name of ['fusion-foil', 'hud-plate', 'pause-plate', 'boss-plate']) {
  const svg = fs.readFileSync(path.join(root, 'assets', 'hud-art1', name + '.svg'), 'utf8');
  assets[name] = 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/'/g, '%27');
}
fs.writeFileSync(path.join(root, 'src', 'hud-art-data.js'),
  '// Generated by node dev/pack-hud-art.cjs from assets/hud-art1.\nconst HUD_ART = ' +
  JSON.stringify(assets, null, 2) + ';\n');
